(async function(){
  var lb=Array.from(document.querySelectorAll("label")).find(function(e){return (e.textContent||"").trim()==="推广专区"});
  if(!lb) return "NO_LABEL";
  var dd=lb.parentElement.querySelector("[class*=dropdown]");
  if(!dd) return "NO_DD";
  dd.click();
  await new Promise(function(r){setTimeout(r,1200)});
  var menu=dd.querySelector("[class*=menu]");
  var items=menu?Array.from(menu.querySelectorAll("[data-value],[class*=item]")).map(function(e){return {v:e.getAttribute("data-value"),t:(e.textContent||"").trim().slice(0,20)}}).filter(function(x){return x.t}):[];
  return JSON.stringify({ddClass:(dd.className||"").toString(),items:items.slice(0,30)});
})()
